const FormField = ({ label, type, name, required, helperText, value, onChange }) => {
  return (
    <div className="form-field">
      <label htmlFor={name}>{label} {required && '*'}</label>
      <input
        type={type}
        id={name}
        name={name}
        required={required}
        value={value}
        onChange={onChange}
      />
      {helperText && <p className="helper-text">{helperText}</p>}
    </div>
  );
};

const ContactForm = () => {
  const [formData, setFormData] = useState({
